import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"7、【师】 坎下坤上","description":"横渠易说 - 7、【师】 坎下坤上","frontmatter":{"title":"7、【师】 坎下坤上","description":"横渠易说 - 7、【师】 坎下坤上"},"headers":[],"relativePath":"zh/classics/hengqu/009.md","filePath":"zh/classics/hengqu/009.md"}'),l={name:"zh/classics/hengqu/009.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_7、【师】-坎下坤上" tabindex="-1">7、【师】 坎下坤上 <a class="header-anchor" href="#_7、【师】-坎下坤上" aria-label="Permalink to “7、【师】 坎下坤上”">​</a></h1><p>丈人刚过，太公近之。刚正、刚中，则是大人圣人，得中道也。太公则必待诛纣时，虽鹰扬，所以为刚过，不得称大人。</p><h3 id="彖曰-师-众也-贞-正也-能以众正-可以王矣。刚中而应-行险而顺-以此毒天下而民从之-吉又何咎矣" tabindex="-1">彖曰：师，众也；贞，正也；能以众正，可以王矣。刚中而应，行险而顺，以此毒天下而民从之，吉又何咎矣! <a class="header-anchor" href="#彖曰-师-众也-贞-正也-能以众正-可以王矣。刚中而应-行险而顺-以此毒天下而民从之-吉又何咎矣" aria-label="Permalink to “彖曰：师，众也；贞，正也；能以众正，可以王矣。刚中而应，行险而顺，以此毒天下而民从之，吉又何咎矣!”">​</a></h3><h3 id="象曰-地中有水-师-君子以容民畜众。" tabindex="-1">象曰：地中有水，师，君子以容民畜众。 <a class="header-anchor" href="#象曰-地中有水-师-君子以容民畜众。" aria-label="Permalink to “象曰：地中有水，师，君子以容民畜众。”">​</a></h3><h3 id="初六-师出以律-否臧凶。-象曰-师出以律-失律凶也。" tabindex="-1">初六，师出以律，否臧凶。 象曰：“师出以律”，失律凶也。 <a class="header-anchor" href="#初六-师出以律-否臧凶。-象曰-师出以律-失律凶也。" aria-label="Permalink to “初六，师出以律，否臧凶。 象曰：“师出以律”，失律凶也。”">​</a></h3><p>师出以律”，师之始也，体柔居贱，不善用律，故凶。</p><h3 id="九二-在师中-吉-无咎。王三锡命。-象曰-在师中吉-承天宠也。-王三锡命-怀万邦也。" tabindex="-1">九二，在师中，吉，无咎。王三锡命。 象曰：“在师中吉”，承天宠也。“王三锡命”，怀万邦也。 <a class="header-anchor" href="#九二-在师中-吉-无咎。王三锡命。-象曰-在师中吉-承天宠也。-王三锡命-怀万邦也。" aria-label="Permalink to “九二，在师中，吉，无咎。王三锡命。 象曰：“在师中吉”，承天宠也。“王三锡命”，怀万邦也。”">​</a></h3><p>怀爱万邦，故所以重将帅。</p><h3 id="六三-师或舆尸-凶。-象曰-师或舆尸-大无功也。" tabindex="-1">六三，师或舆尸，凶。 象曰：“师或舆尸”，大无功也。 <a class="header-anchor" href="#六三-师或舆尸-凶。-象曰-师或舆尸-大无功也。" aria-label="Permalink to “六三，师或舆尸，凶。 象曰：“师或舆尸”，大无功也。”">​</a></h3><p>阴柔之质，履不以正，以此帅众，固不能一。师丈人吉，非阴柔所御。</p><h3 id="六四-师左次-无咎。-象曰-左次无咎-未失常也。" tabindex="-1">六四，师左次，无咎。 象曰：“左次无咎”，未失常也。 <a class="header-anchor" href="#六四-师左次-无咎。-象曰-左次无咎-未失常也。" aria-label="Permalink to “六四，师左次，无咎。 象曰：“左次无咎”，未失常也。”">​</a></h3><p>次之不战之地，则不失其常。</p><h3 id="六五-田有禽-利执言-无咎。长子帅师-弟子舆尸-贞凶。-象曰-长子帅师-以中行也-弟子舆尸-使不当也。" tabindex="-1">六五，田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。 象曰：“长子帅师”，以中行也；“弟子舆尸”，使不当也。 <a class="header-anchor" href="#六五-田有禽-利执言-无咎。长子帅师-弟子舆尸-贞凶。-象曰-长子帅师-以中行也-弟子舆尸-使不当也。" aria-label="Permalink to “六五，田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。 象曰：“长子帅师”，以中行也；“弟子舆尸”，使不当也。”">​</a></h3><p>柔居盛位，见犯乃较，故无咎。任寄非一，行师之凶也。</p><h3 id="上六-大君有命-开国承家-小人勿用。-象曰-大君有命-以正功也。-小人勿用-必乱邦也。" tabindex="-1">上六，大君有命，开国承家，小人勿用。 象曰：“大君有命”，以正功也。“小人勿用”，必乱邦也。 <a class="header-anchor" href="#上六-大君有命-开国承家-小人勿用。-象曰-大君有命-以正功也。-小人勿用-必乱邦也。" aria-label="Permalink to “上六，大君有命，开国承家，小人勿用。 象曰：“大君有命”，以正功也。“小人勿用”，必乱邦也。”">​</a></h3><p>师终必推赏，然小人虽有功，不可胙之以上，长乱也。承，犹继世之承也。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
